// src/storagePatch.js
(function() {
  function getPlatform() {
    if (typeof window === 'undefined') return 'vk';
    var search = window.location.search;
    if (search.indexOf('vk_client=ok') !== -1) return 'ok';
    var ua = navigator.userAgent;
    if (ua.indexOf('Odnoklassniki') !== -1 || ua.indexOf('OKApp') !== -1) return 'ok';
    var hostname = window.location.hostname;
    if (hostname.indexOf('ok.ru') !== -1 || hostname.indexOf('odnoklassniki') !== -1) return 'ok';
    return 'vk';
  }

  var platform = getPlatform();
  if (platform !== 'ok') return;

  var prefix = 'ok_';
  function addPrefix(key) {
    if (key && key.indexOf(prefix) === 0) return key;
    return prefix + key;
  }

  // Оригинальные методы
  var origGetItem = localStorage.getItem;
  var origSetItem = localStorage.setItem;
  var origRemoveItem = localStorage.removeItem;
  var origClear = localStorage.clear;
  var origKey = localStorage.key;

  var cache = {};

  // ----- FAPI инициализация -----
  var fapiReady = false;
  var fapiInitPromise = null;

  function initFAPI() {
    if (fapiInitPromise) return fapiInitPromise;
    fapiInitPromise = new Promise(function(resolve) {
      if (typeof FAPI !== 'undefined' && FAPI.Client) {
        fapiReady = true;
        resolve();
        return;
      }
      var script = document.createElement('script');
      script.src = '//api.ok.ru/js/fapi5.js';
      script.defer = true;
      script.onload = function() {
        if (typeof FAPI !== 'undefined' && FAPI.Client) {
          fapiReady = true;
        }
        resolve();
      };
      script.onerror = function() {
        console.warn('Не удалось загрузить FAPI, используем localStorage');
        resolve();
      };
      document.head.appendChild(script);
    });
    return fapiInitPromise;
  }

  function callFAPI(method, params) {
    return new Promise(function(resolve) {
      if (!fapiReady || typeof FAPI === 'undefined' || !FAPI.Client) {
        resolve(null);
        return;
      }
      try {
        FAPI.Client.call({
          method: method,
          params: params,
          callback: function(data) {
            resolve(data);
          }
        });
      } catch(e) {
        console.warn('Ошибка вызова FAPI:', e);
        resolve(null);
      }
    });
  }

  // ===== ПРОМИС ДЛЯ ОЖИДАНИЯ ЗАГРУЗКИ =====
  var storageInitResolve = null;
  var storageInitPromise = new Promise(function(resolve) {
    storageInitResolve = resolve;
  });
  window.__storageReady = storageInitPromise;

  // Загрузка всех данных из localStorage и FAPI
  function loadAllData() {
    // 1. Читаем из localStorage (с префиксом) – синхронно
    for (var i = 0; i < localStorage.length; i++) {
      var key = origKey.call(localStorage, i);
      if (key && key.indexOf(prefix) === 0) {
        cache[key] = origGetItem.call(localStorage, key);
      }
    }
// Принудительно обновляем store для рекорда, если он есть в кэше
if (cache['ok_tetris_high_score'] && window.store && window.store.dispatch) {
  try {
    var actions = require('../actions').default;
    var score = parseInt(cache['ok_tetris_high_score'], 10) || 0;
    if (score > 0) {
      window.store.dispatch(actions.max(score));
      console.log('🔄 storagePatch: рекорд обновлён из localStorage кэша:', score);
    }
  } catch(e) {}
}
    // 2. Асинхронно загружаем из FAPI и обновляем кэш и localStorage
    initFAPI()
      .then(function() {
        return callFAPI('storage.getAll', {});
      })
      .then(function(data) {
        if (data && data.data) {
          for (var key in data.data) {
            if (data.data.hasOwnProperty(key) && key.indexOf(prefix) === 0) {
              var fapiValue = data.data[key];
              if (cache[key] !== fapiValue) {
                cache[key] = fapiValue;
                origSetItem.call(localStorage, key, fapiValue);
              }
            }
          }
        }
         // Принудительно обновляем store для рекорда после загрузки из FAPI
  if (cache['ok_tetris_high_score'] && window.store && window.store.dispatch) {
    try {
      var actions = require('../actions').default;
      var score = parseInt(cache['ok_tetris_high_score'], 10) || 0;
      if (score > 0) {
        window.store.dispatch(actions.max(score));
        console.log('🔄 storagePatch: рекорд обновлён из FAPI:', score);
      }
    } catch(e) {}
  }
        // ВСЕГДА резолвим промис, даже если данных нет
        if (storageInitResolve) storageInitResolve();
      })
      .catch(function(err) {
        console.warn('Ошибка загрузки из FAPI Storage:', err);
        if (storageInitResolve) storageInitResolve();
      });
  }

  loadAllData();

  // ----- Переопределяем методы localStorage -----
  localStorage.getItem = function(key) {
    var actualKey = addPrefix(key);
    return cache.hasOwnProperty(actualKey) ? cache[actualKey] : null;
  };

  localStorage.setItem = function(key, value) {
    var actualKey = addPrefix(key);
    cache[actualKey] = value;
    origSetItem.call(localStorage, actualKey, value);

    initFAPI().then(function() {
      callFAPI('storage.set', {
        key: actualKey,
        value: value
      }).catch(function(err) {
        console.warn('Ошибка сохранения в FAPI Storage:', err);
      });
    });
  };

  localStorage.removeItem = function(key) {
    var actualKey = addPrefix(key);
    delete cache[actualKey];
    origRemoveItem.call(localStorage, actualKey);
    initFAPI().then(function() {
      callFAPI('storage.set', {
        key: actualKey,
        value: ''
      }).catch(function(err) {
        console.warn('Ошибка удаления из FAPI Storage:', err);
      });
    });
  };

  localStorage.clear = function() {
    var keys = Object.keys(cache);
    cache = {};
    keys.forEach(function(k) {
      origRemoveItem.call(localStorage, k);
    });
  };

  localStorage.key = function(index) {
    var keys = Object.keys(cache);
    return keys[index] || null;
  };

  Object.defineProperty(localStorage, 'length', {
    get: function() { return Object.keys(cache).length; },
    configurable: true
  });

  console.log('✅ OK: FAPI Storage + localStorage (fallback)');
})();


