// src/unit/debugLogger.js
var debugLogs = [];
var debugContainer = null;

export function initDebugLogger() {
  if (debugContainer) return;
  debugContainer = document.createElement('div');
  debugContainer.id = 'debug-console';
  debugContainer.style.cssText =
    'position: fixed; bottom: 10px; left: 10px; right: 10px; max-height: 200px; overflow-y: auto; background: rgba(0,0,0,0.8); color: #0f0; font-size: 12px; font-family: monospace; padding: 10px; z-index: 99999; border-radius: 5px; pointer-events: none;';
  document.body.appendChild(debugContainer);
  // Очищаем старые логи
  debugContainer.innerHTML = '';
}

export function debugLog(message) {
  var timestamp = new Date().toLocaleTimeString();
  var entry = '[' + timestamp + '] ' + message;
  debugLogs.push(entry);
  if (debugContainer) {
    var line = document.createElement('div');
    line.textContent = entry;
    debugContainer.appendChild(line);
    // Прокручиваем вниз
    debugContainer.scrollTop = debugContainer.scrollHeight;
    // Ограничиваем количество строк
    while (debugContainer.children.length > 50) {
      debugContainer.removeChild(debugContainer.firstChild);
    }
  }
  console.log(entry);
}

// Автоматически инициализируем при загрузке
if (typeof window !== 'undefined') {
  window.addEventListener('load', function() {
    initDebugLogger();
    debugLog('🟢 Debug logger initialized');
  });
}


