console.log('🔥 index.js ЗАГРУЖЕН!');
// Инициализируем логгер как можно раньше
initDebugLogger();
debugLog('🚀 Приложение запущено');

var PLATFORM = getPlatform();
logPlatform();
// Если это Одноклассники – начинаем загрузку рекорда как можно раньше
if (PLATFORM === 'ok') {
  console.log('🔄 OK: немедленная загрузка рекорда');
  loadYandexHighScore(store);
}

window.openLeaderboard = fetchYandexLeaderboard;

// Рендерим React немедленно
console.log('🚀 Рендерим React-приложение...');
try {
  render(
    React.createElement(Provider, { store: store },
      React.createElement(App, null)
    ),
    document.getElementById('root')
  );
} catch (e) {
  console.error('Ошибка рендеринга:', e);
/*  document.getElementById('root').innerHTML =
    '<pre style="color:red;font-size:20px;">Ошибка рендеринга: ' + e.message + '\n' + e.stack + '</pre>';
*/}

// ===== АСИНХРОННАЯ ИНИЦИАЛИЗАЦИЯ =====
setTimeout(function() {
  console.log('⏳ Асинхронная инициализация...');

  // ВСЕГДА вызываем initYandexSdk (и для VK, и для OK)
  initYandexSdk()
    .then(function() {
      console.log('✅ VK Bridge инициализирован');
      // Загружаем рекорд
      loadYandexHighScore(store);
      // Синхронизируем звёзды
      loadTotalScore().then(function(total) {
        console.log('⭐ Звёзды синхронизированы:', total);
      }).catch(function(err) {
        console.warn('Ошибка синхронизации звёзд:', err);
      });
      // Синхронизируем достижения
      syncYandexAchievements().then(function() {
        console.log('✅ Достижения синхронизированы при старте');
      });
      // Подписываемся на изменения
      subscribeRecord(store);
      // Показываем баннер
      if (typeof showBannerAd === 'function') {
        showBannerAd();
      }
    })
    .catch(function(err) {
      console.error('Ошибка инициализации VK Bridge:', err);
      // Всё равно загружаем локальные данные
      loadYandexHighScore(store);
      subscribeRecord(store);
    });
}, 100);

window.store = store; 


