export var preloadRewardedAd = function() {
  if (typeof vkBridge === 'undefined') {
    console.log('ℹ️ VK Bridge не найден, предзагрузка невозможна');
    return;
  }
  if (!vkInitialized) {
    console.log('ℹ️ VK не инициализирован, предзагрузка отложена');
    return;
  }
  vkBridge.send('VKWebAppCheckNativeAds', { ad_format: 'reward' })
    .then(function(data) {
      if (data && data.result) {
        console.log('✅ Рекламные материалы для reward предзагружены');
      } else {
        console.log('⚠️ Рекламные материалы не найдены, запрос отправлен');
      }
    })
    .catch(function(err) {
      console.warn('❌ Ошибка предзагрузки рекламы:', err);
    });
};

export var showRewardedAd = function() {
  return new Promise(function(resolve) {
    if (typeof vkBridge === 'undefined') {
      console.log("ℹ️ VK Bridge не найден");
      resolve(false);
      return;
    }
    
    if (!vkInitialized) {
      console.log("ℹ️ VK не инициализирован");
      resolve(false);
      return;
    }
    
    // 官方文档：ad_format: 'reward'[reference:1]
    vkBridge.send('VKWebAppShowNativeAds', { ad_format: 'reward' })
      .then(function(data) {
        // data.result === true 表示成功[reference:2]
        if (data && data.result === true) {
          console.log('✅ Реклама за вознаграждение успешно показана');
           preloadRewardedAd();
          resolve(true);
        } else {
          console.log('⚠️ Реклама не была показана');
          resolve(false);
        }
      })
      .catch(function(error) {
        console.error('❌ Ошибка при показе рекламы:', error);
        resolve(false);
      });
  });
};




